import { useId } from "react";
import type { InputHTMLAttributes } from "react";
import { cn } from "@/lib/cn";

interface FieldProps extends Omit<InputHTMLAttributes<HTMLInputElement>, "id"> {
  etichetta: string;
  /** Testo di aiuto sempre visibile. Sostituisce il placeholder, che sparisce mentre si scrive. */
  aiuto?: string;
  errore?: string;
}

export function Field({ etichetta, aiuto, errore, className, required, ...props }: FieldProps) {
  const id = useId();
  const idAiuto = `${id}-aiuto`;
  const idErrore = `${id}-errore`;

  // Collega input, aiuto ed errore: lo screen reader li legge insieme al campo
  const descrizioni = [aiuto && idAiuto, errore && idErrore].filter(Boolean).join(" ");

  return (
    <div className="flex flex-col gap-1.5">
      <label htmlFor={id} className="text-base font-semibold text-ink">
        {etichetta}
        {required && (
          <span className="ml-1 text-accent-text">
            (obbligatorio)
          </span>
        )}
      </label>

      {aiuto && (
        <p id={idAiuto} className="text-sm text-muted">
          {aiuto}
        </p>
      )}

      <input
        id={id}
        required={required}
        aria-describedby={descrizioni || undefined}
        aria-invalid={errore ? true : undefined}
        className={cn(
          "min-h-11 rounded-brand border-2 bg-paper px-3 py-2 text-base text-ink",
          "focus-visible:outline-2 focus-visible:outline-offset-1 focus-visible:outline-accent-text",
          errore ? "border-[#B3261E]" : "border-muted",
          className,
        )}
        {...props}
      />

      {errore && (
        // role="alert" annuncia l'errore appena compare, senza spostare il focus
        <p id={idErrore} role="alert" className="text-sm font-medium text-[#B3261E]">
          {errore}
        </p>
      )}
    </div>
  );
}

/** Primo elemento focalizzabile della pagina: permette di saltare la navigazione. */
export function SkipLink() {
  return (
    <a
      href="#contenuto"
      className="sr-only-focusable absolute left-4 top-4 z-50 rounded-brand
                 bg-ink px-4 py-3 text-base font-semibold text-paper
                 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-accent"
    >
      Vai al contenuto principale
    </a>
  );
}

/** Unisce classi condizionali senza dipendenze esterne. */
export function cn(...parti: Array<string | false | null | undefined>): string {
  return parti.filter(Boolean).join(" ");
}

import { createClient } from "@supabase/supabase-js";

const url = import.meta.env.VITE_SUPABASE_URL;
const anonKey = import.meta.env.VITE_SUPABASE_ANON_KEY;

/**
 * Client Supabase verso l'istanza self-hosted locale (Podman).
 * Avviala con `npm run db:up` dalla radice del progetto.
 *
 * Usa SOLO la anon key: rispetta le policy RLS. La service_role key bypassa RLS
 * e non deve mai comparire in codice che finisce nel bundle del browser.
 */
export const supabase =
  url && anonKey
    ? createClient(url, anonKey)
    : null;

/** True se la configurazione Supabase è presente: permette all'app di girare anche senza DB. */
export const supabaseAttivo = supabase !== null;

if (!supabaseAttivo && import.meta.env.DEV) {
  console.warn(
    "Supabase non configurato: VITE_SUPABASE_URL o VITE_SUPABASE_ANON_KEY mancanti in .env.\n" +
      "L'app funziona comunque, ma senza persistenza.",
  );
}

